import { configDefaults, defineConfig } from 'vitest/config'

// One root config, one project per package, plus `plugin-form-api` for the
// real-Form probe. Tests never boot Payload or a
// database: they inject fakes. `tests/parity` in the stats package compares
// the TypeScript engine against fixtures generated by Python gbstats
// (scripts/gbstats-parity) and is the correctness gate for the whole repo.
export default defineConfig({
  test: {
    projects: [
      {
        resolve: { conditions: ['@delmaredigital/source', 'module', 'browser', 'development|production'] },
        ssr: { resolve: { conditions: ['@delmaredigital/source', 'module', 'node', 'development|production'] } },
        test: {
          name: 'stats',
          root: 'packages/stats',
          globals: true,
          environment: 'node',
          include: ['tests/**/*.test.ts'],
        },
      },
      {
        resolve: { conditions: ['@delmaredigital/source', 'module', 'browser', 'development|production'] },
        ssr: { resolve: { conditions: ['@delmaredigital/source', 'module', 'node', 'development|production'] } },
        test: {
          name: 'plugin',
          exclude: [...configDefaults.exclude, 'tests/admin/blocks/formApi.v3.test.tsx', 'tests/admin/goals/pickerForm.v3.test.tsx'],
          root: 'packages/plugin',
          globals: true,
          environment: 'node',
          include: ['tests/**/*.test.ts', 'tests/**/*.test.tsx'],
        },
      },
      {
        resolve: { conditions: ['@delmaredigital/source', 'module', 'browser', 'development|production'] },
        ssr: { resolve: { conditions: ['@delmaredigital/source', 'module', 'node', 'development|production'] } },
        test: {
          name: 'plugin-form-api',
          root: 'packages/plugin',
          // Only the real-Form probe needs Vite to handle the public UI's CSS.
          // Keep dependency handling in the other plugin tests unchanged.
          server: { deps: { inline: ['@payloadcms/ui', 'react-image-crop'] } },
          environment: 'jsdom',
          include: ['tests/admin/blocks/formApi.v3.test.tsx', 'tests/admin/goals/pickerForm.v3.test.tsx'],
        },
      },
    ],
    coverage: {
      provider: 'v8',
      reporter: ['text', 'json', 'html'],
      include: ['packages/*/src/**/*.{ts,tsx}'],
      exclude: ['**/*.d.ts', '**/exports/**'],
    },
  },
})
